export const getProjectiles = (world: World, position: Position) =>
  Object.values(getCell(world, position)).filter(
    (target) => PROJECTILE in target
  ) as Entity[];

export const isShootable = (world: World, entity: Entity) =>
  SHOOTABLE in entity &&
  STATS in entity &&
  (!isDead(world, entity) || isDecaying(world, entity)) &&
  !isDecayed(world, entity);

export const getShootable = (
  world: World,
  position: Position,
  fragment = false
) => {
  const targetEntity = Object.values(getCell(world, position)).find((target) =>
    isShootable(world, target)
  ) as Entity | undefined;

  if (targetEntity) return targetEntity;

  const fragmentEntity = getFragment(world, position);

  if (!fragmentEntity) return;

  const structurableEntity = world.getEntityById(
    fragmentEntity[FRAGMENT].structure
  );

  if (!structurableEntity) return;

  if (fragment && isShootable(world, structurableEntity)) return fragmentEntity;

  if (isShootable(world, structurableEntity)) return structurableEntity;
};

export const isBouncable = (world: World, position: Position) =>
  isCollision(world, position) ||
  isSubmerged(world, position) ||
  getLockable(world, position) ||
  getLootable(world, position);

export const getStackableArrow = (world: World, position: Position) => {
  const lootable = getLootable(world, position);

  if (!lootable) return;

  const arrowId = lootable[INVENTORY].items.findLast((itemId: number) => {
    const arrowEntity = world.assertByIdAndComponents(itemId, [ITEM]);
    return arrowEntity[ITEM].stackable === "arrow";
  });

  return arrowId && world.assertById(arrowId);
};

export const shootArrow = (
  world: World,
  origin: Entity,
  bow: Entity,
  overrides: TypedEntity = {}
) => {
  const entity = { ...origin, ...overrides } as TypedEntity<
    "MOVABLE" | "EQUIPPABLE" | "BELONGABLE" | "ORIENTABLE" | "POSITION"
  >;
  const orientation = entity[ORIENTABLE].facing || "up";

  spendItem(world, entity, { stackable: "arrow", amount: 1 });

  // scale sounds by distance to hero
  const heroEntity = world.getEntity([PLAYER, POSITION]);
  play("arrow", {
    variant: 1,
    proximity: heroEntity
      ? 1 /
        (getDistance(
          entity[POSITION],
          heroEntity[POSITION],
          world.metadata.gameEntity[LEVEL].size
        ) +
          1)
      : 0.5,
  });

  const tick =
    world.assertByIdAndComponents(entity[MOVABLE].reference, [REFERENCE])[
      REFERENCE
    ].tick / 2;

  const frameId = world.getEntityId(
    entities.createFrame(world, {
      [REFERENCE]: {
        tick,
        delta: 0,
        suspended: true,
        suspensionCounter: -1,
      },
      [RENDERABLE]: { generation: 0 },
    })
  );
  const hasShadow = !isImmersible(world, entity[POSITION]);
  const material = bow[ITEM].material as Material;
  const sprite = (hasShadow ? shotShadow : shot)[material].default;
  const bowStats = getAbilityStats(bow[ITEM], entity[NPC]?.type);
  const { damage } = calculateDamage(world, bowStats, entity, emptyUnitStats);
  const shotEntity = entities.createShot(world, {
    [BELONGABLE]: { faction: entity[BELONGABLE].faction },
    [MOVABLE]: {
      orientations: [],
      reference: frameId,
      lastInteraction: 0,
      spring: { duration: tick },
      flying: false,
      swimming: false,
    },
    [ORIENTABLE]: { facing: orientation },
    [POSITION]: copy(entity[POSITION]),
    [PROJECTILE]: {
      damage,
      moved: false,
      material,
      shadow: hasShadow,
    },
    [RENDERABLE]: { generation: 0 },
    [SEQUENCABLE]: { states: {} },
    [SPRITE]: sprite,
  });
  registerEntity(world, shotEntity);

  // let arrow move
  createSequence<"arrow", ArrowSequence>(
    world,
    shotEntity,
    "arrow",
    "arrowShot",
    {
      range: 9,
      origin: copy(entity[POSITION]),
      caster: world.getEntityId(origin),
    }
  );
};

export default function setupBallistics(world: World) {
  let referenceGenerations = -1;

  const onUpdate = (delta: number) => {
    const generation = world
      .getEntities([RENDERABLE, REFERENCE])
      .reduce((total, entity) => entity[RENDERABLE].generation + total, 0);

    if (referenceGenerations === generation) return;

    referenceGenerations = generation;

    // handle projectile collision
    const selectedProjectiles = [
      ...world.getEntities([
        ORIENTABLE,
        POSITION,
        PROJECTILE,
        RENDERABLE,
        SEQUENCABLE,
      ]),
    ];
    const heroEntity = world.getEntity([PLAYER, POSITION]);
    const size = world.metadata.gameEntity[LEVEL].size;
    for (const entity of selectedProjectiles) {
      // scale sounds by distance to hero
      const arrowProximity = heroEntity
        ? 1 / (getDistance(entity[POSITION], heroEntity[POSITION], size) + 1)
        : 0.5;

      // hit crossing enemies
      const isFlying = getSequence(world, entity, "arrow");
      const shootable = getShootable(world, entity[POSITION]);
      let bouncable = isBouncable(world, entity[POSITION]);
      const hitBoxes = [];
      const orientation = entity[ORIENTABLE].facing || "up";
      const oppositeOrientation = invertOrientation(orientation);

      // update shadow
      const hasShadow = !isImmersible(world, entity[POSITION]);
      if (entity[PROJECTILE].shadow !== hasShadow) {
        entity[PROJECTILE].shadow = hasShadow;
        const material = entity[PROJECTILE].material;
        const sprite = (hasShadow ? shotShadow : shot)[material].default;
        entity[SPRITE] = sprite;
        rerenderEntity(world, entity);
      }

      if (!isFlying) {
        hitBoxes.push(entity[POSITION]);
      }

      if (entity[PROJECTILE].moved) {
        hitBoxes.push(
          add(entity[POSITION], orientationPoints[oppositeOrientation])
        );
      }

      let hit = false;
      for (const hitBox of hitBoxes) {
        const targetEntity = getShootable(world, hitBox);
        const fragmentEntity =
          getShootable(world, hitBox, true) || targetEntity;

        if (
          fragmentEntity &&
          targetEntity &&
          !isFriendlyFire(world, entity, targetEntity)
        ) {
          if (attemptBubbleAbsorb(world, targetEntity)) {
            bouncable = true;
            break;
          }

          // inflict damage
          const attack = entity[PROJECTILE].damage;
          const { damage, hp } = calculateDamage(
            world,
            { melee: attack },
            {},
            targetEntity
          );
          targetEntity[STATS].hp = hp;

          // propagate damage
          const rootEntity = getRoot(world, targetEntity);
          if (targetEntity !== rootEntity) {
            const { hp } = calculateDamage(
              world,
              { true: damage },
              {},
              rootEntity
            );
            rootEntity[STATS].hp = hp;
            rerenderEntity(world, rootEntity);
          }

          // increment arrow hit counter on target
          if (!isEnemy(world, entity)) {
            fragmentEntity[SHOOTABLE].shots += 1;
          }
          hit = true;
          play("arrow", { variant: 3, proximity: arrowProximity });
          disposeEntity(world, entity, false);

          // add hit marker
          createAmountMarker(
            world,
            fragmentEntity,
            -damage,
            orientation,
            "melee"
          );

          break;
        }
      }
      if (hit) continue;

      // drop arrows only after fully reaching end
      if (isFlying) continue;

      // don't drop enemy arrows
      if (isEnemy(world, entity)) {
        disposeEntity(world, entity);
        continue;
      }

      // stack into arrows
      const arrowStack = getStackableArrow(world, entity[POSITION]);
      if (arrowStack) {
        arrowStack[ITEM].amount += 1;
        const containerEntity = world.assertById(arrowStack[ITEM].carrier);
        rerenderEntity(world, containerEntity);
        disposeEntity(world, entity, false);
        continue;
      }

      // bounce off walls or allies but not oneself
      if (
        bouncable ||
        (shootable &&
          isFriendlyFire(world, entity, shootable) &&
          getSequence(world, entity, "arrow")?.args.caster !==
            world.getEntityId(shootable))
      ) {
        play("arrow", { variant: 2, proximity: arrowProximity });
        play("arrow", { variant: 4, delay: 160, proximity: arrowProximity });
        const targetPosition = add(
          entity[POSITION],
          orientationPoints[oppositeOrientation]
        );

        const lootable = getLootable(world, targetPosition);
        const collecting = getCollecting(world, targetPosition);
        const container = collecting ? undefined : lootable;

        if (!isEnemy(world, entity)) {
          const drop = dropEntity(
            world,
            { [SHOOTABLE]: { shots: 1 } },
            entity[POSITION],
            !!container,
            2,
            container ? undefined : oppositeOrientation
          )[0];

          // add to container that finished bouncing
          if (container) {
            collectItem(world, container, drop);
          }
        }

        disposeEntity(world, entity, false);
        continue;
      }

      // drop finished projectiles
      const arrowEntity = createItemAsDrop(
        world,
        entity[POSITION],
        entities.createItem,
        {
          [ITEM]: {
            stackable: "arrow",
            amount: 1,
            bound: false,
          },
          [SPRITE]: arrow,
        },
        !isImmersible(world, entity[POSITION])
      );
      const containerEntity = world.assertById(arrowEntity[ITEM].carrier);
      registerEntity(world, containerEntity);
      disposeEntity(world, entity);
      continue;
    }
  };

  return { onUpdate };
}
